const without = (items, excluded) => excluded.size ? (items || []).filter(item => !excluded.has(JSON.stringify(item))) : items || [];

export function applyFurnitureCorrections(data) {
  for (const floor of data.floors) {
    const correction = corrections[floor.level];
    if (!correction) continue;
    const excluded = new Set(correction.excludedDoorCurves.map(curve => JSON.stringify(curve)));
    floor.geometry.doorSwings = without(floor.geometry.doorSwings, excluded);
    const tableEdges = new Set((correction.excludedWallSegments || []).map(segment => JSON.stringify(segment)));
    floor.geometry.walls = without(floor.geometry.walls, tableEdges);
    const removedPlan = new Set((correction.excludedPlanSegments || []).map(segment => JSON.stringify(segment)));
    floor.geometry.planLinework = without(floor.geometry.planLinework, removedPlan);
    floor.geometry.curvedTables = correction.tables;
    if (correction.counters) floor.geometry.counters = correction.counters;
    if (correction.chairSeats) {
      const chairs = new Set(correction.chairSeats.map(points => JSON.stringify(points)));
      floor.geometry.tables = without(floor.geometry.tables, chairs);
      floor.geometry.chairSeats = correction.chairSeats;
    }
  }
}
